-- M4 synthetic fulfillment and aftersales. Sources, local workflow and cash ledgers stay separate.
ALTER TABLE sales_order_items ADD COLUMN shipment_ack_qty INTEGER NOT NULL DEFAULT 0 CHECK(shipment_ack_qty>=0);
ALTER TABLE sales_order_items ADD COLUMN aftersale_hold_qty INTEGER NOT NULL DEFAULT 0 CHECK(aftersale_hold_qty>=0);
ALTER TABLE shipments ADD COLUMN sales_order_id UUID;
ALTER TABLE shipments ADD COLUMN sales_order_item_id UUID;
ALTER TABLE shipments ADD COLUMN store_id UUID;
ALTER TABLE shipments ADD COLUMN qty INTEGER NOT NULL DEFAULT 1 CHECK(qty>0);
ALTER TABLE shipments ADD COLUMN source_state VARCHAR(32) NOT NULL DEFAULT 'NOT_CREATED';
ALTER TABLE shipments ADD COLUMN source_version BIGINT NOT NULL DEFAULT 1 CHECK(source_version>0);
ALTER TABLE shipments ADD COLUMN source_digest CHAR(64);
ALTER TABLE shipments ADD COLUMN tracking_version BIGINT NOT NULL DEFAULT 1 CHECK(tracking_version>0);
ALTER TABLE shipments ADD COLUMN acknowledged BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE shipments ADD COLUMN updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE shipments ADD FOREIGN KEY(tenant_id,sales_order_id) REFERENCES sales_orders(tenant_id,id);
ALTER TABLE shipments ADD FOREIGN KEY(tenant_id,sales_order_item_id) REFERENCES sales_order_items(tenant_id,id);
ALTER TABLE shipments ADD FOREIGN KEY(tenant_id,store_id) REFERENCES stores(tenant_id,id);
ALTER TABLE shipments ADD CONSTRAINT ck_shipment_state CHECK(state IN ('NOT_CREATED','LABEL_CREATED','SHIPPED','DELIVERED','LOST','EXCEPTION'));
CREATE UNIQUE INDEX uq_shipment_external ON shipments(tenant_id,purchase_order_id,external_shipment_id);
CREATE INDEX idx_shipment_scope ON shipments(tenant_id,store_id,updated_at DESC,id);
CREATE TABLE shipment_versions(tenant_id UUID NOT NULL,shipment_id UUID NOT NULL,tracking_version BIGINT NOT NULL,carrier_code VARCHAR(80) NOT NULL,tracking_number VARCHAR(128) NOT NULL,source_state VARCHAR(32) NOT NULL,source_version BIGINT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0),observed_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,shipment_id,tracking_version),FOREIGN KEY(tenant_id,shipment_id) REFERENCES shipments(tenant_id,id));
ALTER TABLE shipment_syncs DROP CONSTRAINT shipment_syncs_tenant_id_shipment_id_sales_order_id_key;
ALTER TABLE shipment_syncs ADD COLUMN sales_order_item_id UUID;
ALTER TABLE shipment_syncs ADD COLUMN qty INTEGER NOT NULL DEFAULT 1 CHECK(qty>0);
ALTER TABLE shipment_syncs ADD COLUMN tracking_version BIGINT NOT NULL DEFAULT 1 CHECK(tracking_version>0);
ALTER TABLE shipment_syncs ADD COLUMN provider_key VARCHAR(160);
ALTER TABLE shipment_syncs ADD COLUMN needs_query BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE shipment_syncs ADD COLUMN acknowledged_at TIMESTAMPTZ;
ALTER TABLE shipment_syncs ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE shipment_syncs ADD FOREIGN KEY(tenant_id,sales_order_item_id) REFERENCES sales_order_items(tenant_id,id);
ALTER TABLE shipment_syncs ADD CONSTRAINT ck_sync_state CHECK(state IN ('NOT_SENT','SENDING','ACKED','RETRY_WAIT','BLOCKED'));
CREATE UNIQUE INDEX uq_sync_version ON shipment_syncs(tenant_id,shipment_id,tracking_version);
CREATE UNIQUE INDEX uq_sync_provider_key ON shipment_syncs(tenant_id,provider_key);
CREATE TABLE mock_shipment_configs(tenant_id UUID NOT NULL,shipment_id UUID NOT NULL,behavior VARCHAR(32) NOT NULL DEFAULT 'NORMAL' CHECK(behavior IN ('NORMAL','SUBMIT_5XX','SUBMIT_TIMEOUT_AFTER','QUERY_TIMEOUT','AUTHORITY_MISMATCH','CORRECTION_BLOCKED')),version BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,shipment_id),FOREIGN KEY(tenant_id,shipment_id) REFERENCES shipments(tenant_id,id));
CREATE TABLE mock_shipment_authority(tenant_id UUID NOT NULL,purchase_order_id UUID NOT NULL,external_shipment_id VARCHAR(128) NOT NULL,source_version BIGINT NOT NULL,snapshot JSONB NOT NULL,PRIMARY KEY(tenant_id,purchase_order_id,external_shipment_id),FOREIGN KEY(tenant_id,purchase_order_id) REFERENCES purchase_orders(tenant_id,id));
CREATE TABLE mock_shipment_ack_authority(tenant_id UUID NOT NULL,provider_key VARCHAR(160) NOT NULL,shipment_id UUID NOT NULL,tracking_version BIGINT NOT NULL,snapshot JSONB NOT NULL,submit_calls INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,provider_key),FOREIGN KEY(tenant_id,shipment_id) REFERENCES shipments(tenant_id,id));
CREATE TABLE m4_mock_events(tenant_id UUID NOT NULL,event_id VARCHAR(128) NOT NULL,event_type VARCHAR(48) NOT NULL,aggregate_id UUID NOT NULL,digest CHAR(64) NOT NULL,job_id UUID NOT NULL,PRIMARY KEY(tenant_id,event_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
ALTER TABLE aftersales_cases ADD COLUMN store_id UUID;
ALTER TABLE aftersales_cases ADD COLUMN sales_order_item_id UUID;
ALTER TABLE aftersales_cases ADD COLUMN qty INTEGER NOT NULL DEFAULT 1 CHECK(qty>0);
ALTER TABLE aftersales_cases ADD COLUMN currency CHAR(3) NOT NULL DEFAULT 'CNY' CHECK(currency='CNY');
ALTER TABLE aftersales_cases ADD COLUMN source_state VARCHAR(32) NOT NULL DEFAULT 'REQUESTED';
ALTER TABLE aftersales_cases ADD COLUMN source_version BIGINT NOT NULL DEFAULT 1 CHECK(source_version>0);
ALTER TABLE aftersales_cases ADD COLUMN source_digest CHAR(64);
ALTER TABLE aftersales_cases ADD COLUMN upstream_state VARCHAR(32) NOT NULL DEFAULT 'NO_PURCHASE';
ALTER TABLE aftersales_cases ADD COLUMN reason_code VARCHAR(64);
ALTER TABLE aftersales_cases ADD COLUMN deadline_at TIMESTAMPTZ;
ALTER TABLE aftersales_cases ADD FOREIGN KEY(tenant_id,store_id) REFERENCES stores(tenant_id,id);
ALTER TABLE aftersales_cases ADD FOREIGN KEY(tenant_id,sales_order_item_id) REFERENCES sales_order_items(tenant_id,id);
CREATE UNIQUE INDEX uq_case_external_store ON aftersales_cases(tenant_id,store_id,source_case_id);
CREATE INDEX idx_case_scope ON aftersales_cases(tenant_id,store_id,updated_at DESC,id);
CREATE TABLE aftersales_coordinations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,aftersales_case_id UUID NOT NULL,purchase_order_id UUID NOT NULL,state VARCHAR(32) NOT NULL,upstream_source_state VARCHAR(32) NOT NULL,source_version BIGINT NOT NULL DEFAULT 0,requested_refund_fen BIGINT NOT NULL DEFAULT 0 CHECK(requested_refund_fen>=0),cancellation_reference VARCHAR(160),refund_reference VARCHAR(160),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),UNIQUE(tenant_id,aftersales_case_id,purchase_order_id),FOREIGN KEY(tenant_id,aftersales_case_id) REFERENCES aftersales_cases(tenant_id,id),FOREIGN KEY(tenant_id,purchase_order_id) REFERENCES purchase_orders(tenant_id,id));
CREATE TABLE mock_aftersale_authority(tenant_id UUID NOT NULL,sales_order_id UUID NOT NULL,source_case_id VARCHAR(128) NOT NULL,source_version BIGINT NOT NULL,snapshot JSONB NOT NULL,PRIMARY KEY(tenant_id,sales_order_id,source_case_id),FOREIGN KEY(tenant_id,sales_order_id) REFERENCES sales_orders(tenant_id,id));
CREATE TABLE mock_supplier_aftersale_authority(tenant_id UUID NOT NULL,aftersales_case_id UUID NOT NULL,purchase_order_id UUID NOT NULL,source_version BIGINT NOT NULL,snapshot JSONB NOT NULL,PRIMARY KEY(tenant_id,aftersales_case_id,purchase_order_id),FOREIGN KEY(tenant_id,aftersales_case_id) REFERENCES aftersales_cases(tenant_id,id),FOREIGN KEY(tenant_id,purchase_order_id) REFERENCES purchase_orders(tenant_id,id));
ALTER TABLE refund_transactions ADD COLUMN direction VARCHAR(16) NOT NULL DEFAULT 'SALES' CHECK(direction IN ('SALES','SUPPLIER'));
ALTER TABLE refund_transactions ADD COLUMN currency CHAR(3) NOT NULL DEFAULT 'CNY' CHECK(currency='CNY');
ALTER TABLE refund_transactions ADD COLUMN verified_at TIMESTAMPTZ;
ALTER TABLE refund_transactions ADD COLUMN provider_key VARCHAR(160);
ALTER TABLE refund_transactions ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE refund_transactions ADD CONSTRAINT ck_refund_state CHECK(state IN ('PENDING','VERIFIED','FAILED','UNKNOWN'));
CREATE UNIQUE INDEX uq_refund_provider_key ON refund_transactions(tenant_id,provider_key);
CREATE UNIQUE INDEX uq_m4_sync_event ON outbox_events(tenant_id,aggregate_id) WHERE event_type='M4_SHIPMENT_SYNC';
